argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$rows=@();
Push-Location $repo;
foreach($p in @('app/scripts/operator-lifecycle-r40.ps1','app/scripts/pause-all-r40.cmd','app/scripts/pause-browser-r40.cmd','app/scripts/resume-attach-r40.cmd','app/scripts/resume-managed-r40.cmd')){
  $expected=([string](git rev-parse ('HEAD:'+$p))).Trim();
  $actual=([string](git hash-object $p)).Trim();
  $fi=Get-Item $p;
  $rows += [pscustomobject]@{path=$p;expectedBlob=$expected;actualBlob=$actual;length=$fi.Length;lastWriteUtc=$fi.LastWriteTimeUtc.ToString('o')}
}
Pop-Location;
$procs=@(Get-CimInstance Win32_Process | Where-Object {
  ($_.CommandLine -match 'E:\\WebAIBridge') -or
  ($_.CommandLine -match 'operator-lifecycle-r40|pause-all-r40|resume-managed-r40|resume-attach-r40|pause-browser-r40') -or
  ($_.Name -in @('node.exe','powershell.exe','cmd.exe') -and $_.CommandLine -match '17448|Web AI Bridge')
} | Select-Object ProcessId,ParentProcessId,Name,ExecutablePath,CommandLine);
$services=@(Get-CimInstance Win32_Service | Where-Object { $_.PathName -match 'WebAIBridge|17448' -or $_.Name -match 'WebAI|Bridge' } | Select-Object Name,DisplayName,State,StartMode,ProcessId,PathName);
[pscustomobject]@{files=$rows;processes=$procs;services=$services}|ConvertTo-Json -Depth 6 -Compress
